import sys


def calc(expr: str) -> int | str:
    # Set recursion limit high enough for expression length
    sys.setrecursionlimit(max(sys.getrecursionlimit(), len(expr) + 500))

    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            tokens.append(int(expr[start:i]))
        elif c in "+-*/%^()":
            tokens.append(c)
            i += 1
        else:
            i += 1

    class CalcError(Exception):
        pass

    pos = 0
    num_tokens = len(tokens)

    def peek():
        return tokens[pos] if pos < num_tokens else None

    # Grammar with operator precedence:
    # expr -> term_add
    # term_add -> term_mul ( ('+' | '-') term_mul )*   [left-assoc]
    # term_mul -> term_unary ( ('*' | '/' | '%') term_unary )*  [left-assoc]
    # term_unary -> '-' term_unary | term_pow
    # term_pow -> primary ( '^' term_pow_rhs )?        [right-assoc]
    # Note on precedence:
    # Unary '-' binds looser than '^', so:
    # -2^2 -> -(2^2) = -4
    # But right operand of '^' may start with unary '-':
    # 2^-1 -> 2^(-1) -> error
    # term_pow_rhs can be unary '-' or term_pow, which is term_unary!

    def parse_expr():
        val = parse_mul()
        while pos < num_tokens and peek() in ("+", "-"):
            op = tokens[pos]
            nonlocal_advance()
            rhs = parse_mul()
            if op == "+":
                val = val + rhs
            else:
                val = val - rhs
        return val

    def nonlocal_advance():
        nonlocal pos
        pos += 1

    def parse_mul():
        val = parse_unary()
        while pos < num_tokens and peek() in ("*", "/", "%"):
            op = tokens[pos]
            nonlocal_advance()
            rhs = parse_unary()
            if op == "*":
                val = val * rhs
            elif op == "/":
                if rhs == 0:
                    raise CalcError()
                # Division truncating toward zero
                # In Python: -7 // 2 is -4, but int(-7 / 2) floats or int(Fraction)
                # For exact large ints:
                # abs(val) // abs(rhs), with sign
                sign = -1 if (val < 0) ^ (rhs < 0) else 1
                val = sign * (abs(val) // abs(rhs))
            elif op == "%":
                if rhs == 0:
                    raise CalcError()
                # a % b = a - b * (a / b) using truncating division
                sign = -1 if (val < 0) ^ (rhs < 0) else 1
                q = sign * (abs(val) // abs(rhs))
                val = val - rhs * q
        return val

    def parse_unary():
        if pos < num_tokens and peek() == "-":
            nonlocal_advance()
            val = parse_unary()
            return -val
        elif pos < num_tokens and peek() == "+":
            # Just in case unary plus appears
            nonlocal_advance()
            return parse_unary()
        else:
            return parse_pow()

    def parse_pow():
        val = parse_primary()
        if pos < num_tokens and peek() == "^":
            nonlocal_advance()
            # Right operand of '^' can start with unary minus:
            # 2^-1 is 2^(-1), 2^3^2 is 2^(3^2)
            # Since unary binds looser than ^ normally, but on RHS of ^ it takes effect:
            # parse_unary handles both unary '-' and chained '^'
            rhs = parse_unary()
            if rhs < 0:
                raise CalcError()
            val = pow(val, rhs)
        return val

    def parse_primary():
        nonlocal pos
        t = peek()
        if isinstance(t, int):
            pos += 1
            return t
        elif t == "(":
            pos += 1
            val = parse_expr()
            if pos < num_tokens and tokens[pos] == ")":
                pos += 1
            return val
        else:
            raise CalcError()

    try:
        if not tokens:
            return "error"
        result = parse_expr()
        if pos != num_tokens:
            return "error"
        return result
    except (CalcError, RecursionError):
        return "error"
